/* ================== OUTILS ================== */
const DAY=86400000;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>Math.random().toString(36).slice(2,9)+Date.now().toString(36).slice(-4);
const pad=n=>String(n).padStart(2,'0');
function d0(d){const x=new Date(d);x.setHours(0,0,0,0);return x}
function parseD(s){if(!s)return null;const [y,m,d]=String(s).split('-').map(Number);if(!y||!m||!d)return null;return new Date(y,m-1,d)}
function iso(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function addD(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function diffD(a,b){return Math.round((d0(a)-d0(b))/DAY)}
function fmtD(d,o){if(!d)return '—';return d.toLocaleDateString('fr-CA',o||{day:'numeric',month:'long',year:'numeric'})}
function fmtS(d){return d?d.toLocaleDateString('fr-CA',{day:'numeric',month:'short'}):'—'}
function fmtT(t){const d=new Date(t);return pad(d.getHours())+' h '+pad(d.getMinutes())}
function hm(t){const d=new Date(t);return pad(d.getHours())+':'+pad(d.getMinutes())}
function dur(s){s=Math.max(0,Math.round(s));const h=Math.floor(s/3600),m=Math.floor(s%3600/60);return h?h+' h '+pad(m):m+' min'}
function ago(t){const m=Math.round((Date.now()-t)/60000);if(m<1)return "à l'instant";if(m<60)return 'il y a '+m+' min';const h=Math.floor(m/60);return 'il y a '+h+' h '+pad(m%60)}
function mmss(s){s=Math.max(0,Math.floor(s));const h=Math.floor(s/3600);return (h?h+':':'')+pad(Math.floor(s%3600/60))+':'+pad(s%60)}
function money(n){return (Math.round((+n||0)*100)/100).toLocaleString('fr-CA',{minimumFractionDigits:0,maximumFractionDigits:2})+' $'}
function toast(msg){document.querySelectorAll('.toast').forEach(x=>x.remove());const t=document.createElement('div');t.className='toast';t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),2300)}
function enc(o){return btoa(unescape(encodeURIComponent(JSON.stringify(o))))}
function dec(s){return JSON.parse(decodeURIComponent(escape(atob(s.trim()))))}
async function copy(text,el){try{await navigator.clipboard.writeText(text);toast('Copié')}catch(e){if(el){const r=document.createRange();r.selectNodeContents(el);const s=getSelection();s.removeAllRanges();s.addRange(r)}toast('Texte sélectionné : faites Copier')}}
function nowLocal(t){const d=t?new Date(t):new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}
function art(n){const w=n.split(' ')[0];return MASC.includes(w)?'d\'un ':'d\'une '}
function fruit(w){return FRUITS[Math.max(4,Math.min(42,w))]}
function cm(x){return String(x).replace('.',',')}
function weekInfo(w){return WEEKS.find(x=>w>=x[0]&&w<=x[1])||(w<4?WEEKS[0]:WEEKS[WEEKS.length-1])}
function ppInfo(d){return PP_DAYS.find(x=>d>=x[0]&&d<=x[1])||PP_DAYS[PP_DAYS.length-1]}
function diaperGoal(day){if(day<=1)return [1,1];if(day===2)return [2,2];if(day===3)return [3,2];if(day===4)return [4,3];return [6,3]}
const icon=(n,c)=>'<i class="fa-solid '+n+'"'+(c?' style="color:'+c+'"':'')+'></i>';

/* chemins dans l'état : "parent.plan.p2" */
function getP(p){return p.split('.').reduce((o,k)=>o==null?undefined:o[k],S)}
function setP(p,v){const ks=p.split('.');let o=S;for(let i=0;i<ks.length-1;i++){if(o[ks[i]]==null||typeof o[ks[i]]!=='object')o[ks[i]]={};o=o[ks[i]]}o[ks[ks.length-1]]=v}
/* composants liés à l'état */
const ui={
 check:(p,label,extra)=>'<label class="check"><input type="checkbox" data-act="chk" data-p="'+esc(p)+'" data-k="'+esc(label)+'" '+((getP(p)||{})[label]?'checked':'')+'><span>'+esc(label)+(extra?' <span class="muted xs">'+extra+'</span>':'')+'</span></label>',
 checks:(p,arr)=>'<div class="checks">'+arr.map(x=>ui.check(p,x)).join('')+'</div>',
 text:(p,label,type,ph,rr)=>'<label class="f">'+esc(label)+'<input type="'+(type||'text')+'" id="'+esc(p.replace(/[^a-z0-9]/gi,'_'))+'" data-act="txt" '+(rr?'data-rr="1" ':'')+'data-p="'+esc(p)+'" value="'+esc(getP(p)??'')+'" placeholder="'+esc(ph||'')+'"></label>',
 area:(p,label,ph,h)=>'<label class="f">'+esc(label)+'<textarea id="'+esc(p.replace(/[^a-z0-9]/gi,'_'))+'" data-act="txt" data-p="'+esc(p)+'" placeholder="'+esc(ph||'')+'"'+(h?' style="min-height:'+h+'px"':'')+'>'+esc(getP(p)??'')+'</textarea></label>',
 pick:(p,opts,v)=>'<div class="tri">'+opts.map(o=>'<button class="chip '+(getP(p)===o?'on':'')+'" data-act="pick" data-p="'+esc(p)+'" data-v="'+esc(o)+'">'+esc(o)+'</button>').join('')+'</div>',
 count:(p,arr)=>{const o=getP(p)||{};return arr.filter(x=>o[x]).length}
};
function sh(title,sub,eyebrow){return '<div class="sh">'+(eyebrow?'<span class="eyebrow acc">'+eyebrow+'</span>':'')+'<h1>'+title+'</h1>'+(sub?'<p class="sub">'+sub+'</p>':'')+'</div>'}
function back(act,v,label){return '<button class="btn sm ghost back" data-act="'+act+'" data-v="'+(v||'')+'">'+icon('fa-arrow-left')+(label||'Retour')+'</button>'}
function srcLine(keys){return '<p class="src">Sources : '+keys.map(k=>'<a href="'+SRC[k][1]+'" target="_blank" rel="noopener">'+SRC[k][0]+'</a>').join(' · ')+'</p>'}

/* Photos : IndexedDB, repli en mémoire */
let DB=null,memPhotos=[],photosCache=[];
function openDB(){return new Promise(res=>{try{const r=indexedDB.open('serenaissance-photos',1);r.onupgradeneeded=()=>r.result.createObjectStore('p',{keyPath:'id'});r.onsuccess=()=>{DB=r.result;res()};r.onerror=()=>res()}catch(e){res()}})}
function allPhotos(){return new Promise(res=>{if(!DB)return res(memPhotos.slice());try{const q=DB.transaction('p').objectStore('p').getAll();q.onsuccess=()=>res(q.result.sort((a,b)=>b.t-a.t));q.onerror=()=>res([])}catch(e){res(memPhotos.slice())}})}
function putPhoto(p){return new Promise(res=>{if(!DB){memPhotos=memPhotos.filter(x=>x.id!==p.id);memPhotos.unshift(p);return res()}try{const tx=DB.transaction('p','readwrite');tx.objectStore('p').put(p);tx.oncomplete=()=>res();tx.onerror=()=>res()}catch(e){memPhotos.unshift(p);res()}})}
function delPhoto(id){return new Promise(res=>{if(!DB){memPhotos=memPhotos.filter(x=>x.id!==id);return res()}try{const tx=DB.transaction('p','readwrite');tx.objectStore('p').delete(id);tx.oncomplete=()=>res();tx.onerror=()=>res()}catch(e){res()}})}
function shrink(file){return new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>{const im=new Image();im.onload=()=>{const k=Math.min(1,1400/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.84))};im.onerror=rej;im.src=fr.result};fr.onerror=rej;fr.readAsDataURL(file)})}
/* ================== CALCULS ================== */
function preg(p){const r={};const ddr=parseD(p.ddr),ed=parseD(p.echoDate),eq=parseD(p.dpaEquipe);const cyc=Number(p.cycle)||28;
  r.ddrDPA=ddr?addD(ddr,280+(cyc-28)):null;const sa=(p.echoSA===''||p.echoSA==null)?null:Number(p.echoSA);
  r.echoDPA=(ed&&sa!=null)?addD(ed,280-(sa*7+(Number(p.echoJ)||0))):null;
  if(eq){r.dpa=eq;r.src='Date fixée par l\'équipe de soins'}
  else if(r.echoDPA&&r.ddrDPA){const g=Math.abs(diffD(r.echoDPA,r.ddrDPA));if(g>7){r.dpa=r.echoDPA;r.src='Échographie (écart de '+g+' jours avec les règles)';r.warn=true}else{r.dpa=r.ddrDPA;r.src='Dernières règles, confirmées par l\'échographie'}}
  else if(r.echoDPA){r.dpa=r.echoDPA;r.src='Échographie'}else if(r.ddrDPA){r.dpa=r.ddrDPA;r.src='Dernières règles'}
  if(!r.dpa)return null;const ga=280-diffD(r.dpa,new Date());r.gaDays=ga;r.w=Math.floor(ga/7);r.d=((ga%7)+7)%7;r.left=diffD(r.dpa,new Date());r.tri=ga<98?1:ga<196?2:3;return r}
function gaAt(dpa,date){const ga=280-diffD(dpa,date);return [Math.floor(ga/7),((ga%7)+7)%7]}
function stage(){const b=parseD(S.parent.naissance.date);if(b)return {k:'pp',day:diffD(new Date(),b),birth:b};const g=preg(S.parent);if(g)return {k:'preg',g};return {k:'none'}}
function last24(types){const c=Date.now()-DAY;return S.logs.filter(l=>l.t>=c&&(!types||types.includes(l.type)))}

/* ================== PARENTS · ACCUEIL ================== */
function ring(frac,inner,lbl,gold){const r=70,C=2*Math.PI*r;const f=Math.max(0,Math.min(1,frac));
  const g=gold!=null?'<circle cx="82" cy="82" r="'+r+'" fill="none" stroke="var(--gold)" stroke-opacity=".5" stroke-width="12" stroke-dasharray="'+(C*gold)+' '+C+'"/>':'';
  return '<div class="ring"><svg viewBox="0 0 164 164"><circle cx="82" cy="82" r="'+r+'" fill="none" stroke="var(--soft2)" stroke-width="12"/>'+g+'<circle cx="82" cy="82" r="'+r+'" fill="none" stroke="var(--accent)" stroke-width="12" stroke-linecap="round" stroke-dasharray="'+(C*f)+' '+C+'"/></svg><div class="c">'+inner+'<span class="lbl">'+lbl+'</span></div></div>'}
function pAccueil(){const st=stage(),p=S.parent;let h='';const nm=p.prenom&&p.prenom!=='Exemple'?esc(p.prenom):'';
  if(st.k==='none'){return hautAccueil()+'<div class="card"><div class="hero"><div class="stack" style="gap:8px"><span class="script">Bienvenue</span><h1>Votre cocon, de la grossesse au 4<sup>e</sup> trimestre</h1><p class="muted">Entrez une date : l\'appli calcule votre semaine, la taille de bébé et les examens à venir.</p><button class="btn" data-act="tab" data-v="suivi" style="align-self:flex-start">'+icon('fa-calendar-days')+'Remplir mon dossier</button></div><div class="blob"><img src="'+'/couple.jpg'+'" alt="Couple qui attend un bébé"></div></div></div>'+doulaCard()}
  if(st.k==='preg'){const g=st.g,f=fruit(g.w),wi=weekInfo(g.w);
    h+='<div class="sh"><span class="script">Bonjour'+(nm?' '+nm:'')+'</span></div>';
    h+=hautAccueil();
    h+='<div class="card"><div class="ring-wrap">'+ring(g.gaDays/280,'<span class="big num">'+g.w+'</span><span class="small muted num">+ '+g.d+' j</span>','semaines')+
     '<div class="stack" style="gap:8px"><span class="eyebrow acc">'+g.tri+'<sup>e</sup> trimestre'+(g.w>=38&&g.w<=42?' · votre doula est de garde':'')+'</span><h2>Bébé a la taille '+art(f[0])+esc(f[0])+'</h2><p class="muted small num">Environ '+cm(f[1])+' cm'+(f[2]?' · '+(f[2]>=1000?cm((f[2]/1000).toFixed(1))+' kg':f[2]+' g'):'')+' (moyenne)</p><p class="small">'+(g.left>0?'<b class="num">'+g.left+'</b> jours avant la date prévue, le '+fmtD(g.dpa):g.left===0?'C\'est la date prévue aujourd\'hui.':'Date prévue dépassée de <b>'+(-g.left)+'</b> jour(s).')+'</p></div></div></div>';
    h+='<div class="quick">'+[['kickStart','fa-shoe-prints','Mouvements'],['contr','fa-stopwatch','Contractions'],['humeur','fa-face-smile','Humeur'],['symptome','fa-notes-medical','Symptômes']].map(q=>'<button class="qbtn" data-act="'+q[0]+'">'+icon(q[1])+q[2]+'</button>').join('')+'</div>';
    h+=kickCard()+contrCard();
    h+='<div class="card"><span class="eyebrow acc">Cette semaine</span><div class="grid2 resp"><div class="soft"><b>'+icon('fa-baby')+' Bébé</b><p class="small">'+wi[2]+'</p></div><div class="soft"><b>'+icon('fa-person-pregnant')+' Vous</b><p class="small">'+wi[3]+'</p></div></div></div>';
    h+=todoCard(g.w);
    const nx=EXAMS.find(e=>e[1]>=g.w);if(nx)h+='<div class="card"><div class="li" style="padding:0;border:0"><div class="ic">'+icon('fa-stethoscope')+'</div><div class="tx"><span class="eyebrow acc">Prochain repère · '+(nx[0]===nx[1]?nx[0]:nx[0]+'-'+nx[1])+' SA</span><b>'+nx[2]+'</b><span>'+nx[3]+'</span></div></div></div>';
    if(g.w>=34)h+='<button class="btn sage" data-act="birthForm">'+icon('fa-baby')+'Bébé est né</button>';
  } else {const day=st.day,info=ppInfo(day),bb=p.naissance.prenomBebe;
    h+='<div class="sh"><span class="script">'+(bb?'Bienvenue '+esc(bb):'Bienvenue bébé')+'</span></div>';
    h+=hautAccueil();
    h+='<div class="card"><div class="ring-wrap">'+ring(Math.min(day,90)/90,'<span class="big num">'+day+'</span>','jour'+(day>1?'s':'')+' de vie',40/90)+
     '<div class="stack" style="gap:8px"><span class="eyebrow acc">'+(day<=40?'Mois d\'or · jour '+day+' sur 40':day<=90?'4e trimestre · jour '+day+' sur 90':'Après le 4e trimestre')+'</span><h2>'+(bb?esc(bb):'Bébé')+' a '+(day<14?day+' jour'+(day>1?'s':''):Math.floor(day/7)+' semaines'+(day%7?' et '+day%7+' j':''))+'</h2><p class="small">'+info[2]+'</p><p class="xs muted"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:var(--gold);opacity:.7"></span> 40 premiers jours &nbsp; <span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:var(--accent)"></span> 90 jours</p></div></div></div>';
    h+=timerCard();
    h+='<div class="quick">'+[['feed','fa-person-breastfeeding','Tétée'],['biberon','fa-bottle-droplet','Biberon'],['tirage','fa-pump-medical','Tirage'],['couche','fa-droplet','Couche'],['sommeil','fa-moon','Sommeil'],['humeur','fa-face-smile','Mon moral']].map(q=>'<button class="qbtn" data-act="'+q[0]+'">'+icon(q[1])+q[2]+'</button>').join('')+'</div>';
    h+=dayStats(day);
    h+='<div class="card"><span class="eyebrow acc">'+info[1]+'</span><div class="grid2 resp"><div class="soft"><b>'+icon('fa-baby')+' Bébé</b><p class="small">'+info[2]+'</p></div><div class="soft"><b>'+icon('fa-spa')+' Vous</b><p class="small">'+info[3]+'</p></div></div></div>';
    if(day<=60)h+=moralCard();
  }
  h+=doulaCard();
  h+='<button class="btn ghost" data-act="go" data-v="infos|alertes">'+icon('fa-triangle-exclamation')+'Signaux d\'alerte : quand appeler</button>';
  return h}
function todoCard(w){const items=[];const p=S.parent;
  if(w>=20&&w<=30&&!Object.keys(p.peurs).length)items.push(['preparer|peurs','Remplir « Mes peurs et mes besoins »','À faire chacun de son côté, puis en parler avec la doula.']);
  if(w>=24&&ui.count('parent.prep',PREP)<6)items.push(['preparer|prep','Préparer ma naissance','Une liste pour arriver sereine au grand jour.']);
  if(w>=28&&!Object.keys(p.plan).length)items.push(['preparer|plan','Commencer mon plan de naissance','4 parties, à revoir avec la doula et votre professionnel.']);
  if(w>=30)items.push(['preparer|respiration','Pratiquer la respiration','Quelques minutes par jour avec votre partenaire.']);
  if(w>=34&&ui.count('parent.valise',Object.values(VALISE).flat())<10)items.push(['preparer|valise','Préparer la valise','Idéalement prête vers 35-36 semaines.']);
  if(w>=34)items.push(['preparer|quarante','Planifier mes 40 jours','Repos, chaleur, repas, visiteurs.']);
  if(w>=36)items.push(['infos|A2','Est-ce le vrai travail ?','Les différences, et quand appeler.']);
  if(!items.length)return '';
  return '<div class="card"><span class="eyebrow acc">À faire maintenant</span><div class="list">'+items.slice(0,4).map(i=>'<button class="li" data-act="go" data-v="'+i[0]+'" style="background:none;border-left:0;border-right:0;border-top:0;text-align:left;cursor:pointer;width:100%;color:inherit"><div class="ic">'+icon('fa-check')+'</div><div class="tx"><b>'+i[1]+'</b><span>'+i[2]+'</span></div>'+icon('fa-chevron-right','var(--muted)')+'</button>').join('')+'</div></div>'}
function doulaCard(){const D=DOULA;if(!D)return '';const nm=doulaNomP();return '<div class="card tint"><div class="row between"><div><span class="eyebrow acc">Ma doula</span><h3>'+esc(nm)+'</h3></div><button class="btn sm" data-act="tab" data-v="madoula">'+icon('fa-comments')+'Écrire</button></div>'+(D.telephone?'<p class="small">Appelle (pas seulement un texto) dès les premiers signes, aux eaux ou au départ : <a class="num" href="tel:'+esc(D.telephone.replace(/[^0-9+]/g,''))+'"><b>'+esc(D.telephone)+'</b></a></p>':'')+(D.remplacante_nom?'<p class="xs muted">Remplaçante : '+esc(D.remplacante_nom)+(D.remplacante_tel?' · '+esc(D.remplacante_tel):'')+'</p>':'')+'<p class="xs muted">Urgence : 911 ou ton hôpital d\'abord, ta doula ensuite. France : 15 ou 112.</p></div>'}
function moralCard(){return '<div class="card"><span class="eyebrow acc">Comment va le moral ?</span><p class="small">Depuis les deux dernières semaines…</p>'+ui.check('parent.moral','Je me suis souvent sentie triste, déprimée ou sans espoir')+ui.check('parent.moral','J\'ai eu peu d\'intérêt ou de plaisir à faire les choses')+((S.parent.moral||{})['Je me suis souvent sentie triste, déprimée ou sans espoir']||(S.parent.moral||{})['J\'ai eu peu d\'intérêt ou de plaisir à faire les choses']?'<div class="banner acc">'+icon('fa-comments')+'<div>Merci de l\'avoir noté. Parlez-en à votre doula et à votre médecin, au CLSC ou au 811 : ça se soigne. Idées de vous faire du mal : <b>988</b> ou <b>911</b> (France : 3114).</div></div>':'<p class="xs muted">Ces deux questions sont celles que votre doula pose à chaque contact. Elles ne posent pas de diagnostic.</p>')+'</div>'}
function dayStats(day){const feeds=last24(['sein','biberon']),cou=last24(['couche']);const wet=cou.filter(c=>c.pipi).length,sol=cou.filter(c=>c.selle).length;const g=diaperGoal(day);
  const lastF=S.logs.filter(l=>l.type==='sein'||l.type==='biberon').sort((a,b)=>b.t-a.t)[0];const lastS=S.logs.filter(l=>l.type==='sein').sort((a,b)=>b.t-a.t)[0];
  const bib=last24(['biberon']).reduce((s,l)=>s+(+l.ml||0),0),tir=last24(['tirage']).reduce((s,l)=>s+(+l.ml||0),0);
  let h='<div class="card"><div class="row between"><span class="eyebrow acc">Dernières 24 heures</span>'+(lastF?'<span class="pill acc">Dernier boire '+ago(lastF.t)+(lastS?' · prochain : sein '+(lastS.side==='G'?'droit':'gauche'):'')+'</span>':'')+'</div><div class="grid3">'+
   '<div class="stat '+(feeds.length>=8?'ok':'warn')+'"><b>'+feeds.length+'</b><span>boires (8+ attendus)</span></div><div class="stat '+(wet>=g[0]?'ok':'warn')+'"><b>'+wet+'</b><span>couches mouillées ('+g[0]+'+ au jour '+Math.max(1,day)+')</span></div><div class="stat '+(sol>=g[1]?'ok':'warn')+'"><b>'+sol+'</b><span>selles ('+g[1]+'+ attendues)</span></div></div>';
  if(bib||tir)h+='<div class="grid2"><div class="stat"><b>'+bib+' ml</b><span>au biberon</span></div><div class="stat"><b>'+tir+' ml</b><span>tirés</span></div></div>';
  if(day<=42&&S.logs.length&&(wet<g[0]||sol<g[1]||feeds.length<8))h+='<p class="xs muted">Moins que le repère ? Notez bien chaque boire et chaque couche. Si ça se confirme, appelez le 811 ou votre professionnel le jour même.</p>';
  return h+'</div>'}

/* ---------- Minuteurs ---------- */
function timerCard(){const T=S.timer;if(!T)return '';const s=(Date.now()-T.start)/1000;
  return '<div class="card" style="border-color:var(--accent)"><div class="row between"><span class="eyebrow acc"><span class="live"></span>&nbsp; Tétée en cours · sein '+(T.side==='G'?'gauche':'droit')+'</span><span class="xs muted">depuis '+fmtT(T.t0||T.start)+'</span></div><div class="timer" id="tick" data-start="'+T.start+'">'+mmss(s)+'</div><div class="row"><button class="btn" data-act="feedStop">'+icon('fa-stop')+'Terminer</button><button class="btn ghost" data-act="feedSwitch">'+icon('fa-right-left')+'Changer de sein</button><button class="btn ghost sm" data-act="feedCancel">Annuler</button></div></div>'}
function kickCard(){const K=S.kick;if(!K)return '';const s=(Date.now()-K.start)/1000;const done=K.count>=6;const over=s>7200;
  return '<div class="card" style="border-color:var(--accent)"><div class="row between"><span class="eyebrow acc"><span class="live"></span>&nbsp; Mouvements depuis '+fmtT(K.start)+'</span><span class="small muted num" id="tick" data-start="'+K.start+'">'+mmss(s)+'</span></div><div class="row" style="gap:18px"><span class="timer">'+K.count+'</span><span class="small muted">mouvement'+(K.count>1?'s':'')+' sentis<br>Repère : 6 en 2 heures</span></div>'+
   (done?'<div class="banner sage">'+icon('fa-check')+'<div>6 mouvements atteints. Vous pouvez terminer la séance.</div></div>':over?'<div class="banner bad">'+icon('fa-phone')+'<div><b>Moins de 6 mouvements en 2 heures :</b> appelez votre lieu de naissance ou votre professionnel maintenant.</div></div>':'')+
   '<div class="row"><button class="btn" data-act="kickAdd">'+icon('fa-plus')+'J\'ai senti bébé</button><button class="btn ghost" data-act="kickStop">Terminer</button></div></div>'}
function contrList(){return S.logs.filter(l=>l.type==='contraction').sort((a,b)=>a.t-b.t)}
function contrStats(){const L=contrList().filter(l=>l.t>Date.now()-3600e3);if(L.length<2)return null;const iv=[];for(let i=1;i<L.length;i++)iv.push((L[i].t-L[i-1].t)/1000);return {n:L.length,ai:iv.reduce((a,b)=>a+b,0)/iv.length,ad:L.reduce((a,b)=>a+b.sec,0)/L.length,span:(L[L.length-1].t-L[0].t)/60000}}
function contrCard(force){const A=S.contrActive,st=contrStats();if(!A&&!S.showContr&&!force)return '';const recent=contrList().slice(-6).reverse();
  let h='<div class="card"><div class="row between"><span class="eyebrow acc">Minuteur de contractions</span>'+(force?'':'<button class="btn sm ghost" data-act="contrHide">Fermer</button>')+'</div>';
  h+=A?'<div class="timer" id="tick" data-start="'+A+'">'+mmss((Date.now()-A)/1000)+'</div><button class="btn" data-act="contrEnd">'+icon('fa-stop')+'Fin de la contraction</button>':'<button class="btn" data-act="contrStart">'+icon('fa-play')+'Début de la contraction</button>';
  if(st){const five=st.ai<=330&&st.ad>=55&&st.span>=50;h+='<div class="grid3"><div class="stat"><b>'+st.n+'</b><span>dans la dernière heure</span></div><div class="stat"><b>'+mmss(st.ai)+'</b><span>de début à début</span></div><div class="stat"><b>'+Math.round(st.ad)+' s</b><span>durée moyenne</span></div></div>'+(five?'<div class="banner gold">'+icon('fa-phone')+'<div>Rythme 5-1-1 atteint (aux 5 min, 1 min chacune, depuis 1 h). Suivez la consigne de votre équipe, et appelez votre doula.</div></div>':'')}
  if(recent.length)h+='<div class="list">'+recent.map(c=>'<div class="li"><div class="tx"><b>'+fmtT(c.t)+'</b><span>durée '+c.sec+' s</span></div><button class="icon-btn" data-act="delLog" data-id="'+c.id+'" aria-label="Supprimer">'+icon('fa-trash')+'</button></div>').join('')+'</div>';
  return h+'<p class="xs muted">Eaux qui crèvent, saignement rouge clair, liquide vert ou brun, bébé qui bouge moins : appelez sans attendre, peu importe le rythme.</p></div>'}

/* ================== PARENTS · SUIVI ================== */
function pSuivi(){const p=S.parent,st=stage();let h='';
  if(st.k==='pp'){const day=st.day,sel=S.ppSel??day,info=ppInfo(sel);
    h+=sh('Mon 4<sup>e</sup> trimestre','Jour par jour, jusqu\'au jour 120');
    h+='<div class="card"><h2>Jour '+sel+(sel===day?' (aujourd\'hui)':'')+' · '+info[1]+'</h2><input type="range" id="ppRange" min="0" max="120" value="'+sel+'" data-act="ppSel" style="width:100%;accent-color:var(--accent)"><div class="row between xs muted"><span>Naissance</span><span>40 j</span><span>90 j</span><span>120 j</span></div><div class="grid2 resp"><div class="soft"><b>'+icon('fa-baby')+' Bébé</b><p class="small">'+info[2]+'</p></div><div class="soft"><b>'+icon('fa-spa')+' Maman</b><p class="small">'+info[3]+'</p></div></div></div>';
    h+='<div class="card"><span class="eyebrow acc">Examens et rendez-vous</span><div class="timeline">'+PP_EXAMS.map(e=>{const c=day>e[1]?'done':day>=e[0]?'now':'';return '<div class="tl '+c+'"><span class="w">Jour '+e[0]+(e[1]!==e[0]?' à '+e[1]:'')+' · '+fmtS(addD(st.birth,e[0]))+'</span><b>'+e[2]+'</b><p class="small muted">'+e[3]+'</p></div>'}).join('')+'</div></div>';
    h+=retourCard();
    h+='<div class="card"><span class="eyebrow acc">Naissance</span><p>'+esc(p.naissance.prenomBebe||'Bébé')+' est né(e) le '+fmtD(st.birth)+(p.naissance.heure?' à '+esc(p.naissance.heure):'')+'.</p><div class="row"><button class="btn sm ghost" data-act="birthForm">'+icon('fa-pen')+'Modifier</button><button class="btn sm ghost" data-act="go" data-v="souvenirs|recit">Mon récit de naissance</button></div></div>';
    return h}
  const g=preg(p);
  h+=sh('Mon dossier de grossesse','Tout se recalcule à chaque changement');
  h+='<div class="card"><div class="grid2 resp">'+ui.text('parent.prenom','Mon prénom')+ui.text('parent.partenaire','Partenaire')+ui.text('parent.lieu','Lieu de naissance prévu')+ui.text('parent.prof','Professionnel de suivi')+'</div>'+
   '<div class="soft" style="gap:10px"><b class="small">1. Dernières règles</b><div class="grid2">'+ui.text('parent.ddr','1er jour','date',0,1)+ui.text('parent.cycle','Cycle (jours)','number',0,1)+'</div>'+(g&&g.ddrDPA?'<p class="xs muted">Date calculée : '+fmtD(g.ddrDPA)+'</p>':'')+'</div>'+
   '<div class="soft" style="gap:10px"><b class="small">2. Échographie de datation</b><div class="grid3">'+ui.text('parent.echoDate','Date','date',0,1)+ui.text('parent.echoSA','Semaines','number',0,1)+ui.text('parent.echoJ','Jours','number',0,1)+'</div>'+(g&&g.echoDPA?'<p class="xs muted">Date calculée : '+fmtD(g.echoDPA)+'</p>':'')+'</div>'+
   '<div class="soft" style="gap:10px"><b class="small">3. Date prévue donnée par l\'équipe (a priorité)</b>'+ui.text('parent.dpaEquipe','Date prévue','date',0,1)+'</div>'+
   '</div>';
  if(g){h+='<div class="card"><div class="row between"><div><span class="eyebrow acc">Résultat</span><h2>'+g.w+' semaines + '+g.d+' jours</h2></div><span class="pill acc">'+g.tri+'<sup>e</sup> trimestre</span></div><p>Date prévue : <b>'+fmtD(g.dpa)+'</b></p><p class="xs muted">Source : '+g.src+'</p>'+(g.warn?'<div class="banner gold">'+icon('fa-circle-info')+'<div>Les règles et l\'échographie divergent de plus de 7 jours : l\'échographie est retenue.</div></div>':'')+'<div class="prog"><i style="width:'+Math.min(100,Math.max(0,g.gaDays/280*100))+'%"></i></div><div class="grid3"><div class="stat"><b>'+fmtS(addD(g.dpa,-21))+'</b><span>37 SA · à terme</span></div><div class="stat"><b>'+fmtS(addD(g.dpa,-14))+'</b><span>38 SA · garde de la doula</span></div><div class="stat"><b>'+fmtS(addD(g.dpa,14))+'</b><span>42 SA</span></div></div></div>';
    const wk=S.wkSel??Math.max(4,Math.min(42,g.w)),wi=weekInfo(wk),f=fruit(wk);
    h+='<div class="card"><span class="eyebrow acc">Semaine par semaine</span><h2>Semaine '+wk+(wk===g.w?' (actuelle)':'')+' · '+esc(f[0])+'</h2><input type="range" id="wkRange" min="4" max="42" value="'+wk+'" data-act="wkSel" style="width:100%;accent-color:var(--accent)"><p class="xs muted num">Semaine du '+fmtD(addD(g.dpa,(wk-40)*7))+' · environ '+cm(f[1])+' cm'+(f[2]?', '+f[2]+' g':'')+'</p><div class="grid2 resp"><div class="soft"><b class="small">Bébé</b><p class="small">'+wi[2]+'</p></div><div class="soft"><b class="small">Vous</b><p class="small">'+wi[3]+'</p></div></div></div>';
    h+='<div class="card"><span class="eyebrow acc">Examens et repères</span><div class="timeline">'+EXAMS.map(e=>{const c=g.w>e[1]?'done':g.w>=e[0]?'now':'';return '<div class="tl '+c+'"><span class="w">'+(e[0]===e[1]?e[0]:e[0]+'-'+e[1])+' SA · vers le '+fmtS(addD(g.dpa,(e[0]-40)*7))+'</span><b>'+e[2]+'</b><p class="small muted">'+e[3]+'</p></div>'}).join('')+'</div><p class="xs muted">Le calendrier exact dépend de votre province ou pays et de votre équipe.</p></div>';
    h+='<button class="btn sage" data-act="birthForm">'+icon('fa-baby')+'Bébé est né</button>'}
  return h}
const RT_CHECK=['Présenter le biberon ou le gobelet 2-3 semaines avant (par une autre personne)','Constituer une réserve de lait au congélateur','Parler à l\'employeur : pauses et local pour tirer le lait','Préparer le tire-lait, sac isotherme, contenants identifiés','Faire 1-2 journées d\'essai avec la gardienne','Prévoir des repas simples pour la 1re semaine'];
function retourCard(){const R=S.parent.retour;const stash=S.logs.filter(l=>l.type==='tirage'&&l.dest==='congelateur').reduce((s,l)=>s+(+l.ml||0),0)-S.logs.filter(l=>l.type==='biberon'&&l.lait==='congele').reduce((s,l)=>s+(+l.ml||0),0);
  const need=Math.round((+R.heures||0)*30);const rd=parseD(R.date);const left=rd?diffD(rd,new Date()):null;
  return '<details class="acc"><summary>'+icon('fa-briefcase','var(--accent)')+'Retour au travail et réserve de lait '+(left!=null&&left>=0?'<span class="pill acc">dans '+left+' j</span>':'')+'<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><div class="grid2">'+ui.text('parent.retour.date','Date du retour','date',0,1)+ui.text('parent.retour.heures','Heures loin de bébé par jour','number',0,1)+'</div><div class="grid3"><div class="stat"><b>'+Math.max(0,stash)+' ml</b><span>au congélateur</span></div><div class="stat"><b>'+need+' ml</b><span>besoin estimé par jour</span></div><div class="stat"><b>'+(need?cm((Math.max(0,stash)/need).toFixed(1)):'—')+'</b><span>jour(s) couverts</span></div></div><p class="xs muted">Repère courant : environ 30 ml par heure d\'absence pour un bébé allaité de 1 à 6 mois.</p>'+ui.checks('parent.retour.check',RT_CHECK)+'<p class="xs muted">Canada : congés de maternité et parentaux (assurance-emploi, ou RQAP au Québec). France : congé maternité puis congé parental.</p></div></details>'}

/* ================== PARENTS · JOURNAL ================== */
const LOGMETA={mvt:['fa-shoe-prints','Mouvements'],humeur:['fa-face-smile','Humeur'],symptome:['fa-notes-medical','Symptômes'],contraction:['fa-stopwatch','Contraction'],sein:['fa-person-breastfeeding','Tétée'],biberon:['fa-bottle-droplet','Biberon'],tirage:['fa-pump-medical','Tirage'],couche:['fa-droplet','Couche'],sommeil:['fa-moon','Sommeil'],poids:['fa-weight-scale','Poids'],note:['fa-pen','Note'],soin:['fa-spa','Soins de maman']};
const MOODS=[['fa-face-sad-tear','Très difficile'],['fa-face-frown','Difficile'],['fa-face-meh','Correct'],['fa-face-smile','Bien'],['fa-face-laugh-beam','Très bien']];
const SYMPTOMS=['Nausées','Fatigue','Brûlures d\'estomac','Maux de dos','Crampes','Contractions','Enflure','Maux de tête','Insomnie','Constipation','Essoufflement','Pertes vaginales'];
const STOOL=['Méconium (noir)','Transition (vert)','Jaune moutarde','Brun','Autre (à noter)'];
function logText(l){switch(l.type){case 'mvt':return l.count+' mouvements en '+dur(l.sec);case 'humeur':return MOODS[l.v][1]+(l.note?' · '+esc(l.note):'');case 'symptome':return esc((l.list||[]).join(', '))+(l.note?' · '+esc(l.note):'');case 'contraction':return 'Durée '+l.sec+' s';case 'sein':return 'Sein '+(l.side==='G'?'gauche':l.side==='D'?'droit':'les deux')+' · '+dur(l.sec);case 'biberon':return (l.ml||'?')+' ml · '+({maternel:'lait maternel frais',congele:'lait maternel congelé',preparation:'préparation commerciale'}[l.lait]||'');case 'tirage':return (l.ml||'?')+' ml · '+({frigo:'au frigo',congelateur:'au congélateur',donne:'donné tout de suite'}[l.dest]||'');case 'couche':return [l.pipi?'pipi':'',l.selle?'selle'+(l.couleur?' ('+esc(l.couleur.toLowerCase())+')':''):''].filter(Boolean).join(' + ');case 'sommeil':return dur(l.sec)+(l.note?' · '+esc(l.note):'');case 'poids':return cm((l.g/1000).toFixed(3))+' kg';default:return esc(l.note||'')}}
function pJournal(){const st=stage(),pp=st.k==='pp';let h=sh('Mon journal',pp?'Tétées, couches, sommeil et récupération':'Mouvements, contractions, humeur et symptômes');
  const types=pp?['sein','biberon','tirage','couche','sommeil','poids','humeur','soin','note']:['mvt','contraction','humeur','symptome','note'];
  h+='<div class="quick">'+types.map(t=>'<button class="qbtn" data-act="'+(t==='sein'?'feed':t==='mvt'?'kickStart':t==='contraction'?'contr':t)+'">'+icon(LOGMETA[t][0])+LOGMETA[t][1]+'</button>').join('')+'</div>';
  h+=pp?timerCard():kickCard()+contrCard();
  if(pp){if(st.day<=10)h+=firstWeek(st.birth);h+=weekChart();h+=weightCard(st)}
  const f=S.jf||'tout';const days={};
  S.logs.filter(l=>f==='tout'||l.type===f).sort((a,b)=>b.t-a.t).slice(0,200).forEach(l=>{const k=iso(new Date(l.t));(days[k]=days[k]||[]).push(l)});
  h+='<div class="seg">'+['tout',...types].map(t=>'<button class="chip '+(f===t?'on':'')+'" data-act="jf" data-v="'+t+'">'+(t==='tout'?'Tout':LOGMETA[t][1])+'</button>').join('')+'</div>';
  const keys=Object.keys(days);if(!keys.length)h+='<div class="card dash small muted" style="text-align:center">Rien encore ici. Touchez un bouton ci-dessus pour noter votre première entrée.</div>';
  keys.forEach(k=>{h+='<div class="card flat" style="gap:0"><span class="eyebrow acc">'+fmtD(parseD(k),{weekday:'long',day:'numeric',month:'long'})+'</span><div class="list">'+days[k].map(l=>'<div class="li"><div class="ic">'+icon(LOGMETA[l.type][0])+'</div><div class="tx"><b>'+LOGMETA[l.type][1]+' · '+fmtT(l.t)+'</b><span>'+logText(l)+'</span></div><button class="icon-btn" data-act="delLog" data-id="'+l.id+'" aria-label="Supprimer">'+icon('fa-trash')+'</button></div>').join('')+'</div></div>'});
  return h}
function firstWeek(birth){let rows='';for(let d=1;d<=7;d++){const a=+birth+(d-1)*DAY,b=a+DAY;const L=S.logs.filter(l=>l.t>=a&&l.t<b);const f=L.filter(l=>l.type==='sein'||l.type==='biberon').length,w=L.filter(l=>l.type==='couche'&&l.pipi).length,s=L.filter(l=>l.type==='couche'&&l.selle).length;const future=a>Date.now();
  rows+='<tr><td><b>Jour '+d+'</b></td><td><div class="dots">'+Array.from({length:12},(_,i)=>'<i class="'+(i<f?'f':'')+'"></i>').join('')+'</div>'+(future?'':'<span class="xs muted">'+f+' tétée(s)</span>')+'</td><td class="num">'+(future?'':w+' / '+s)+'</td><td class="xs muted">'+COUCHES_ATT[d-1]+'</td></tr>'}
  return '<div class="card"><span class="eyebrow acc">Tétées et couches · la première semaine</span><div class="scroll-x"><table class="tbl"><thead><tr><th>Jour</th><th>Tétées (8+ / 24 h)</th><th>Mouillées / selles</th><th>Attendu</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="banner bad">'+icon('fa-phone')+'<div class="small">Appelez le 811 ou votre professionnel le jour même si : moins de couches que prévu · urine foncée ou cristaux orangés après le jour 3 · encore du méconium au jour 5 · bébé difficile à réveiller pour boire · moins de 8 tétées par 24 h · jaunisse qui augmente.</div></div></div>'}
function weekChart(){const out=[];for(let i=6;i>=0;i--){const d=d0(addD(new Date(),-i)),e=+d+DAY;const L=S.logs.filter(l=>l.t>=+d&&l.t<e);out.push({d,f:L.filter(l=>l.type==='sein'||l.type==='biberon').length,c:L.filter(l=>l.type==='couche').length})}
  const mx=Math.max(10,...out.map(o=>Math.max(o.f,o.c)));
  return '<div class="card"><div class="row between"><span class="eyebrow acc">7 derniers jours</span><span class="xs muted"><span style="display:inline-block;width:10px;height:10px;border-radius:3px;background:var(--accent)"></span> boires &nbsp;<span style="display:inline-block;width:10px;height:10px;border-radius:3px;background:var(--sage)"></span> couches</span></div><div class="bars">'+out.map(o=>'<div class="bar"><div style="display:flex;gap:3px;align-items:flex-end;height:100%;width:100%;justify-content:center"><div style="display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;flex:1"><em>'+o.f+'</em><i style="height:'+(o.f/mx*78)+'%"></i></div><div style="display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;flex:1"><em>'+o.c+'</em><i class="s" style="height:'+(o.c/mx*78)+'%"></i></div></div><small>'+o.d.toLocaleDateString('fr-CA',{weekday:'short'}).replace('.','')+'</small></div>').join('')+'</div></div>'}
function weightCard(st){const W=S.logs.filter(l=>l.type==='poids').sort((a,b)=>a.t-b.t);if(!W.length)return '';const b0=+S.parent.naissance.poids||W[0].g;const last=W[W.length-1];const pct=((last.g-b0)/b0*100);
  return '<div class="card"><span class="eyebrow acc">Poids de bébé</span><div class="grid3"><div class="stat"><b>'+cm((b0/1000).toFixed(2))+' kg</b><span>naissance</span></div><div class="stat"><b>'+cm((last.g/1000).toFixed(2))+' kg</b><span>dernière pesée · '+fmtS(new Date(last.t))+'</span></div><div class="stat '+(pct<-10?'warn':'ok')+'"><b>'+(pct>0?'+':'')+cm(pct.toFixed(1))+' %</b><span>depuis la naissance</span></div></div><p class="xs muted">Une perte jusqu\'à 7 à 10 % les premiers jours est fréquente; la plupart des bébés reprennent leur poids vers 10 à 14 jours. Votre équipe interprète la courbe.</p></div>'}

/* ================== PARENTS · PRÉPARER ================== */
const PREP_TILES=[
 ['plan','fa-clipboard-list','Mon plan de naissance','4 parties + une page pour l\'équipe',()=>Object.values(S.parent.plan).filter(Boolean).length+' choix'],
 ['situations','fa-route','Situations particulières','Si le plan change · méthode BRAIN'],
 ['cahier','fa-pen-to-square','Mon cahier de préparation','10 questions à deux',()=>Object.values(S.parent.cahier).filter(Boolean).length+'/10'],
 ['peurs','fa-cloud','Mes peurs et mes besoins','Vers 20 à 30 semaines'],
 ['prep','fa-list-check','Préparer ma naissance','La liste pour arriver sereine',()=>ui.count('parent.prep',PREP)+'/'+PREP.length],
 ['valise','fa-suitcase-rolling','Ma valise','Maman, bébé, partenaire',()=>{const a=Object.values(VALISE).flat();return ui.count('parent.valise',a)+'/'+a.length}],
 ['contacts','fa-address-book','Mes contacts importants','À photographier et coller sur le frigo'],
 ['qpro','fa-user-doctor','Questions à mon professionnel','Cochez, notez les réponses'],
 ['partenaire','fa-people-arrows','Aide-mémoire du partenaire','Phase par phase, pressions, mots'],
 ['positions','fa-person-walking','Positions pendant le travail','Changer aux 30 à 60 minutes'],
 ['respiration','fa-wind','Respiration et relaxation','Dès 30 semaines, quelques minutes par jour'],
 ['affirmations','fa-star','Cartes d\'affirmations','36 phrases pour le jour J'],
 ['quarante','fa-mug-hot','Mon plan des 40 jours','Le Mois d\'or : qui m\'aide ?'],
 ['souv','fa-camera','Nos souvenirs','Photos, récit de naissance, premières fois']
];
function pPreparer(){const s=S.sub;if(s==='souv'){S.tab='souvenirs';S.sub='';return pSouvenirs()}if(s&&PSUB[s])return back('sub','','Préparer')+PSUB[s]();
  return sh('Préparer ma naissance','Tous les outils de votre pochette Sérénaissance')+'<div class="tiles">'+PREP_TILES.map(t=>'<button class="tile" data-act="sub" data-v="'+t[0]+'"><span class="ti">'+icon(t[1])+'</span><b>'+t[2]+'</b><span>'+t[3]+'</span>'+(t[4]?'<span class="pill acc" style="align-self:flex-start">'+t[4]()+'</span>':'')+'</button>').join('')+'</div>'}
const PSUB={
 plan(){const p=S.parent,v=S.planV||'edit';let h=sh('Mon plan de naissance','Il vous appartient. Votre doula vous aide à formuler vos souhaits, sans y mettre les siens.');
  h+='<div class="seg"><button class="chip '+(v==='edit'?'on':'')+'" data-act="planV" data-v="edit">Remplir</button><button class="chip '+(v==='coup'?'on':'')+'" data-act="planV" data-v="coup">Page pour l\'équipe</button></div>';
  if(v==='coup')return h+planCoup();
  h+='<div class="card"><span class="eyebrow acc">1 de 4 · En un coup d\'œil</span><div class="grid2 resp">'+ui.text('parent.prenom','Mon nom')+ui.text('parent.partenaire','Partenaire')+'<label class="f">Doula<input type="text" value="'+esc(doulaNomP())+'" disabled></label>'+ui.text('parent.prof','Professionnel de suivi')+ui.text('parent.allergies','Allergies')+'</div>'+ui.area('parent.planF.important1','Le plus important pour moi','',70)+'</div>';
  PLAN.forEach((part,i)=>{h+='<div class="card"><span class="eyebrow acc">'+(i+2)+' de 4 · '+part.t+'</span>'+part.groups.map(g=>'<p class="grp-t">'+g[0]+'</p>'+ui.checks('parent.plan',g[1])).join('');
   if(part.soins)h+='<p class="grp-t">Soins de bébé</p><div class="stack" style="gap:10px">'+part.soins.map((s,j)=>'<div class="stack" style="gap:4px"><span class="small"><b>'+s+'</b></span>'+ui.pick('parent.soins.s'+j,['J\'accepte','Je refuse','Je veux en discuter'])+'</div>').join('')+'</div>';
   (part.fields||[]).forEach(f=>{h+=f[0]==='important'||f[0]==='autres2'?ui.area('parent.planF.'+f[0],f[1],'',80):ui.text('parent.planF.'+f[0],f[1])});h+='</div>'});
  h+='<div class="banner acc">'+icon('fa-lightbulb')+'<div class="small">Ajoutez une ligne pour présenter votre doula : « Notre doula, [prénom], est présente pour notre soutien émotionnel et notre confort. » Présentez votre plan à votre médecin ou sage-femme avant l\'accouchement, et mettez-en 2 copies dans la valise.</div></div>';
  return h},
 situations(){let h=sh('Situations particulières','Réfléchir d\'avance aide à rester actrice de vos choix');
  h+='<div class="card"><span class="eyebrow acc">Avant toute décision</span><div class="brain">'+BRAIN.map(b=>'<div><b>'+b[0]+'</b><span>'+b[1]+'</span></div>').join('')+'</div><p class="xs muted">'+BRAIN.map(b=>b[1]+' : '+b[2]).join(' · ')+'</p></div>';
  SITUATIONS.forEach((s,i)=>{h+='<div class="card"><h3>'+s[0]+'</h3><p class="small">'+s[1]+'</p>'+ui.area('parent.situ.s'+i,'Mes souhaits','',60)+'</div>'});return h},
 cahier(){return sh('Mon cahier de préparation','Prenez une soirée à deux. Vos réponses deviendront votre plan de naissance.')+'<div class="card">'+CAHIER.map((q,i)=>ui.area('parent.cahier.q'+i,(i+1)+'. '+q,'',60)).join('')+'</div>'},
 peurs(){const P=S.parent.peurs;let h=sh('Mes peurs et mes besoins','À remplir chacun de son côté, puis à en parler avec la doula. Il n\'y a pas de bonne ou de mauvaise réponse.');
  h+='<div class="card"><span class="eyebrow acc">Ce qui m\'inquiète · 0 = pas du tout, 4 = beaucoup</span>'+PEURS.map(x=>'<div class="stack" style="gap:4px"><span class="small"><b>'+x+'</b></span><div class="tri">'+[0,1,2,3,4].map(n=>'<button class="chip '+(P[x]===n?'on':'')+'" data-act="peur" data-k="'+esc(x)+'" data-v="'+n+'">'+n+'</button>').join('')+'</div></div>').join('')+'</div>';
  const hi=PEURS.filter(x=>P[x]>=3);if(hi.length)h+='<div class="banner gold">'+icon('fa-comments')+'<div class="small">À aborder à votre prochaine rencontre : <b>'+hi.join(', ')+'</b>.</div></div>';
  h+='<div class="card"><span class="eyebrow acc">En mots</span>'+ui.area('parent.peursT.peur','Ce qui me fait le plus peur','',60)+ui.area('parent.peursT.origine','D\'où vient cette peur (si je le sais)','',60)+ui.area('parent.peursT.securite','Ce qui m\'aiderait à me sentir en sécurité','',60)+'</div><div class="card"><span class="eyebrow acc">Mon partenaire</span>'+ui.area('parent.peursT.partInq','Ce qui l\'inquiète','',60)+ui.area('parent.peursT.partAide','Comment il ou elle veut m\'aider','',60)+'</div><p class="xs muted">Outil de réflexion, pas un test. Si l\'anxiété empêche de dormir ou de fonctionner, parlez-en à votre médecin, au CLSC ou à un psychologue.</p>';return h},
 prep(){return sh('Préparer ma naissance','Cochez au fur et à mesure')+'<div class="card">'+ui.checks('parent.prep',PREP)+'</div>'},
 valise(){return sh('Ma valise','Prête vers 35-36 semaines')+Object.entries(VALISE).map(([k,v])=>'<div class="card"><div class="row between"><span class="eyebrow acc">'+k+'</span><span class="pill acc">'+ui.count('parent.valise',v)+'/'+v.length+'</span></div>'+ui.checks('parent.valise',v)+'</div>').join('')},
 contacts(){return sh('Mes contacts importants','Faites une capture d\'écran : elle vous suivra partout')+'<div class="card"><div class="banner bad">'+icon('fa-truck-medical')+'<div class="small"><b>Urgence : 911</b> (France : 15 ou 112) · Info-Santé / Télé-Soins : <b>811</b> · Ligne de crise (appel ou texto) : <b>988</b></div></div><div class="grid2 resp">'+CONTACTS.map(c=>ui.text('parent.contacts.'+c[0],c[1],c[0]==='adr'?'text':'tel')).join('')+'</div></div>'},
 qpro(){return sh('Questions à mon professionnel','Cochez celles qui vous intéressent et notez les réponses')+Object.entries(QPRO).map(([k,v])=>'<div class="card"><span class="eyebrow acc">'+k+'</span>'+v.map((q,i)=>ui.check('parent.qpro',q)+((S.parent.qpro||{})[q]?ui.text('parent.qproR.'+k.slice(0,3)+i,'Réponse'):'')).join('')+'</div>').join('')+'<div class="card">'+ui.area('parent.qproR.autres','Mes autres questions','',70)+'</div>'},
 partenaire(){let h=sh('Aide-mémoire du partenaire','Votre présence compte plus que tout. Vous n\'avez pas besoin d\'être parfait : vous avez besoin d\'être là.');
  h+='<div class="card"><span class="eyebrow acc">6 gestes simples, à tout moment</span><ul class="clean small"><li>Tenez-lui la main, restez près de son visage</li><li>Écoutez-la, sans chercher à régler quoi que ce soit</li><li>Offrez-lui à boire entre les contractions (et buvez aussi)</li><li>Rappelez-lui combien elle est forte</li><li>Une compresse chaude dans le bas du dos, une fraîche dans le cou</li><li>Massages et caresses, si elle le souhaite</li></ul></div>';
  h+=PARTENAIRE.map(p=>'<details class="acc"><summary>'+esc(p[0])+'<i class="fa-solid fa-chevron-down chev"></i></summary><div class="body"><p class="small muted"><i>'+esc(p[1])+'</i></p><ul class="clean small">'+p[2].map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div></details>').join('');
  h+='<div class="card"><span class="eyebrow acc">Vos mains · trois pressions pour le bas du dos</span>'+PRESSIONS.map(p=>'<div class="soft"><b class="small">'+p[0]+'</b><p class="small">'+p[1]+'</p></div>').join('')+'<p class="xs muted">Le secret pour tenir des heures : appuyez avec le poids de votre corps, bras presque tendus. Relayez-vous avec la doula.</p></div>';
  h+='<div class="card"><span class="eyebrow acc">Les règles d\'or du toucher</span><ul class="clean small">'+TOUCHER.map(x=>'<li>'+x+'</li>').join('')+'</ul>'+ui.text('parent.planF.signal','Notre signal « arrête »')+'</div>';
  h+='<div class="grid2 resp"><div class="card"><span class="eyebrow acc">À dire</span><ul class="clean small">'+MOTS_OUI.map(x=>'<li>« '+x+' »</li>').join('')+'</ul></div><div class="card"><span class="eyebrow acc">À éviter</span><ul class="clean small">'+MOTS_NON.map(x=>'<li>'+(x.includes('blagues')?x:'« '+x+' »')+'</li>').join('')+'</ul></div></div>';
  h+='<div class="card"><span class="eyebrow acc">Respirer avec elle</span><ol class="small" style="margin:0;padding-left:20px;display:flex;flex-direction:column;gap:5px"><li>Au début de la contraction, une grande inspiration ensemble.</li><li>Expirez lentement, plus longtemps que l\'inspiration, comme pour souffler une chandelle sans l\'éteindre.</li><li>Si elle s\'emballe, main sur son épaule, respirez lentement près d\'elle.</li><li>À la fin, une grande respiration de « bienvenue au repos ».</li></ol></div>';
  h+='<div class="banner gold">'+icon('fa-triangle-exclamation')+'<div class="small"><b>Avec une péridurale :</b> on change de position avec l\'infirmière, jamais seul · soutenez bien la jambe engourdie · aucune chaleur sur une zone engourdie · ne touchez pas au cathéter ni aux appareils.</div></div>';
  h+='<div class="card"><span class="eyebrow acc">Prendre soin de vous</span><ul class="clean small"><li>Mangez et buvez : vous aussi, vous travaillez</li><li>Prenez des pauses : la doula reste avec la mère</li><li>Dormez quand elle dort, au début du travail</li><li>Vos émotions comptent : parlez-en, pendant et après</li></ul><p class="xs muted">Si vous vous sentez dépassé, c\'est normal. Sortez respirer quelques minutes : la doula reste avec la mère.</p></div>';
  return h},
 positions(){return sh('Positions pendant le travail','Changer de position toutes les 30 à 60 minutes aide bébé à descendre et à tourner')+Object.entries(POSITIONS).map(([k,v])=>'<div class="card"><span class="eyebrow acc">'+k+'</span><ul class="clean small">'+v.map(x=>'<li>'+x+'</li>').join('')+'</ul></div>').join('')+'<div class="banner acc">'+icon('fa-lightbulb')+'<div class="small">Si une position ne fait pas de bien, changez. Votre corps est votre meilleur guide; la doula vous aidera à trouver ce qui vous soulage.</div></div>'},
 respiration(){const T=S.breath;let h=sh('Respiration et relaxation','À pratiquer quelques minutes par jour avec votre partenaire dès 30 semaines');
  h+='<div class="card" style="align-items:center;text-align:center"><span class="eyebrow acc">Pratique guidée · 4 secondes, puis 6</span><div id="breath" class="aff" style="width:100%;font-style:normal">'+(T?'Inspirez…':'Prête ?')+'</div><button class="btn" data-act="breath">'+(T?icon('fa-stop')+'Arrêter':icon('fa-play')+'Commencer')+'</button></div>';
  return h+RESPI.map(r=>'<div class="card"><h3>'+r[0]+'</h3><p class="small">'+r[1]+'</p></div>').join('')},
 affirmations(){const i=S.affI||0;return sh('Cartes d\'affirmations','Choisissez celles qui vous parlent : votre doula les apportera le jour J')+'<div class="card"><div class="aff">'+esc(AFFIRM[i])+'</div><div class="row between"><button class="btn sm ghost" data-act="aff" data-v="-1">'+icon('fa-arrow-left')+'Précédente</button><span class="xs muted num">'+(i+1)+' / '+AFFIRM.length+'</span><button class="btn sm ghost" data-act="aff" data-v="1">Suivante'+icon('fa-arrow-right')+'</button></div>'+ui.check('parent.affFav',AFFIRM[i],'(mes préférées)')+'</div>'+(Object.values(S.parent.affFav||{}).some(Boolean)?'<div class="card"><span class="eyebrow acc">Mes préférées</span><ul class="clean small">'+AFFIRM.filter(a=>(S.parent.affFav||{})[a]).map(a=>'<li>'+a+'</li>').join('')+'</ul></div>':'')},
 quarante(){return sh('Mon plan des 40 jours','Le Mois d\'or : prendre soin de la mère pour qu\'elle puisse prendre soin de son bébé')+'<div class="card"><span class="eyebrow acc">Mes piliers</span>'+ui.checks('parent.quarante',QUARANTE_PILIERS)+'</div><div class="card"><span class="eyebrow acc">Qui m\'aide ?</span><div class="grid2 resp">'+QUARANTE_TACHES.map((t,i)=>ui.text('parent.quaranteQui.t'+i,t)).join('')+'</div></div><div class="card"><span class="eyebrow acc">Mes repas et mes visiteurs</span>'+ui.text('parent.quaranteT.repas','Qui prépare ou livre les repas ?')+ui.text('parent.quaranteT.congeles','Repas congelés prêts (nombre)','number')+ui.text('parent.quaranteT.vis1','Bienvenus dès la 1re semaine')+ui.text('parent.quaranteT.vis2','Plus tard')+ui.text('parent.quaranteT.regle','Règle de visite (durée, lavage des mains…)')+ui.area('parent.quaranteT.signaux','Mes signaux pour demander de l\'aide','',60)+'</div>'}
};
function planCoup(){const p=S.parent,pl=p.plan,F=p.planF||{};const chosen=PLAN.flatMap(x=>x.groups).map(g=>[g[0],g[1].filter(x=>pl[x])]).filter(g=>g[1].length);
  const soins=(PLAN[1].soins||[]).map((s,j)=>[s,(p.soins||{})['s'+j]]).filter(x=>x[1]);
  let t='MON PLAN DE NAISSANCE\n'+(p.prenom||'')+(p.partenaire?' · partenaire : '+p.partenaire:'')+'\nDate prévue : '+(preg(p)?fmtD(preg(p).dpa):'—')+' · Doula : '+doulaNomP()+'\nProfessionnel : '+(p.prof||'')+' · Allergies : '+(p.allergies||'aucune')+'\n\n';
  chosen.forEach(g=>{t+=g[0].toUpperCase()+'\n'+g[1].map(x=>'- '+x).join('\n')+'\n\n'});if(soins.length)t+='SOINS DE BÉBÉ\n'+soins.map(s=>'- '+s[0]+' : '+s[1]).join('\n')+'\n\n';if(F.codeword)t+='Mot de code : '+F.codeword+'\n';if(F.important1)t+='LE PLUS IMPORTANT POUR MOI\n'+F.important1+'\n';
  t+='\nMerci de prendre le temps de lire mes souhaits. Je vous remercie de m\'informer et de me consulter avant chaque décision.';
  let h='<div class="card" style="background:var(--white)"><div class="row between" style="flex-wrap:nowrap"><div style="min-width:0"><span class="eyebrow acc">Plan de naissance · en un coup d\'œil</span><h2>'+esc(p.prenom||'Mon nom')+'</h2></div><img src="/logo.png" alt="Académie Sérénaissance" style="height:38px;width:auto;flex:none"></div><p class="small">Date prévue : <b>'+(preg(p)?fmtD(preg(p).dpa):'—')+'</b> · Partenaire : <b>'+esc(p.partenaire||'—')+'</b> · Doula : <b>'+esc(doulaNomP())+'</b><br>Professionnel : <b>'+esc(p.prof||'—')+'</b> · Allergies : <b>'+esc(p.allergies||'—')+'</b></p>';
  h+=chosen.length?'<div class="grid2 resp">'+chosen.map(g=>'<div class="soft"><b class="grp-t" style="margin:0">'+g[0]+'</b><ul class="clean small">'+g[1].map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>').join('')+'</div>':'<p class="small muted">Cochez vos souhaits dans « Remplir » : ils apparaîtront ici.</p>';
  if(soins.length)h+='<div class="soft"><b class="grp-t" style="margin:0">Soins de bébé</b><ul class="clean small">'+soins.map(s=>'<li>'+s[0]+' : <b>'+s[1]+'</b></li>').join('')+'</ul></div>';
  if(F.important1)h+='<div class="soft"><b class="grp-t" style="margin:0">Le plus important pour moi</b><p class="small">'+esc(F.important1)+'</p></div>';
  h+='</div><div class="row"><button class="btn" data-act="copyTxt" data-t="'+esc(t)+'">'+icon('fa-copy')+'Copier le texte</button></div><p class="xs muted">Montrez cette page à l\'équipe sur votre téléphone, ou copiez le texte pour l\'envoyer à votre doula.</p>';return h}

