function pInfos(){const s=S.sub;if(s==='alertes')return back('sub','','Bibliothèque')+alertesPage();const f=FICHES.find(x=>x.id===s);if(f)return back('sub','','Bibliothèque')+fichePage(f);
  let h=sh('Ma bibliothèque','Les fiches de votre pochette, appuyées sur des sources reconnues');
  h+='<button class="cl" data-act="sub" data-v="alertes" style="border-color:var(--bad)"><div class="av" style="background:var(--bad-soft);color:var(--bad)">'+icon('fa-triangle-exclamation')+'</div><div style="flex:1;min-width:0"><b>Signaux d\'alerte</b><p class="xs muted">Gardez cette page près du téléphone. En cas de doute, appelez.</p></div>'+icon('fa-chevron-right','var(--muted)')+'</button>';
  const cats=[...new Set(FICHES.map(f=>f.cat))];cats.forEach(c=>{h+='<p class="grp-t">'+c+'</p><div class="tiles">'+FICHES.filter(f=>f.cat===c).map(f=>'<button class="tile" data-act="sub" data-v="'+f.id+'"><span class="ti">'+icon(f.ic)+'</span><b>'+f.t+'</b><span>Fiche '+f.id+'</span></button>').join('')+'</div>'});
  return h}
function fichePage(f){return sh(f.t,'',f.cat+' · '+f.id)+f.blocks.map(b=>'<div class="card"><span class="eyebrow acc">'+b[0]+'</span><ul class="clean small">'+b[1].map(x=>'<li>'+x+'</li>').join('')+'</ul></div>').join('')+(f.note?'<div class="banner acc">'+icon('fa-lightbulb')+'<div class="small">'+f.note+'</div></div>':'')+(f.id==='A3'?'<div class="card"><span class="eyebrow acc">Avant une intervention : BRAIN</span><div class="brain">'+BRAIN.map(b=>'<div><b>'+b[0]+'</b><span>'+b[1]+'</span></div>').join('')+'</div></div>':'')+srcLine(f.src)}
function alertesPage(){const box=(t,arr,lvl)=>'<div class="card"><span class="eyebrow acc">'+t+'</span><p class="xs muted">'+lvl+'</p><ul class="clean small">'+arr.map(x=>'<li>'+x+'</li>').join('')+'</ul></div>';
  return sh('Signaux d\'alerte','Il vaut mieux appeler pour rien')+'<div class="banner bad">'+icon('fa-truck-medical')+'<div><b>911</b> urgence (France : <b>15</b> ou <b>112</b>) · <b>811</b> Info-Santé / Télé-Soins · <b>988</b> ligne de crise'+(DOULA&&DOULA.telephone?' · Ma doula : <b class="num">'+esc(DOULA.telephone)+'</b>':'')+'</div></div>'+box('Pendant la grossesse',ALERTES.grossesse,'Hôpital ou 911 sans attendre')+box('Après la naissance · pour bébé',ALERTES.bebe,'Consulter rapidement ou 911')+box('Après la naissance · pour moi',ALERTES.moi,'Consulter rapidement ou 911')+'<div class="card"><span class="eyebrow acc">Pendant le travail à la maison</span><p class="small">Saignement abondant, convulsions, difficulté à respirer, cordon visible ou senti, envie de pousser incontrôlable ou tête visible avant le départ : <b>ne partez pas en voiture</b>, appelez le 911 et suivez les consignes du répartiteur. Dans le doute, choisissez toujours le niveau le plus urgent.</p></div>'+srcLine(['inspq','scp','sogc'])}
